async function describeInfrastructureLayout(companyId) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'describeInfrastructureLayout',
        companyId: companyId
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to describe infrastructure layout');
    }

    return {
      success: true,
      layout: result.layout,
      companyId: companyId,
      message: `Generated infrastructure layout description for company ${companyId}`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
